head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst60700";
scwin.searchType2 = null;
scwin.notiType2 = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.searchType2 = $c.util.getComponent('searchType2');
        scwin.notiType2 = $c.util.getComponent('notiType2');
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst60700.onpageload' });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function () {
    await scwin.fnSearch();
    $("#type1").attr("checked", true);
    scwin.searchType2.setStyle("display", "none");
    scwin.notiType2.setStyle("display", "none");
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.init();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60700.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst60700.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnSearchInit_onclick
 * @description btn_fnSearchInit 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchInit_onclick = async function(e){
    try {
        await scwin.fnSearchInit(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst60700.btn_fnSearchInit_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/common/zipcd.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchInit
 * @description fn Search Init 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchInit = async function () {
    if ($("#type1").is(":checked")) {
        if (($c.util.getComponent('ipt_searchWord1').getValue() == null ? '' : String($c.util.getComponent('ipt_searchWord1').getValue())) === '') {
            await $c.win.alert("검색할 도로명을 입력해 주세요.");
            return;
        }
        if ($c.util.getComponent('ipt_searchWord1').getValue().length === 1) {
            await $c.win.alert("도로명을 2자이상 입력해 주세요.");
            return;
        }
        if ($c.util.getComponent('ipt_searchWord1').getValue().includes('%')) {
            await $c.win.alert("입력한 도로명에 '%' 문자가 포함되어 있어 처리할 수 없습니다.");
            return;
        }
        $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord1").getValue() || ''));
    } else {
        if ($("#type2").is(":checked")) {
            if (($c.util.getComponent('ipt_searchBldgNm').getValue() == null ? '' : String($c.util.getComponent('ipt_searchBldgNm').getValue())) === '') {
                await $c.win.alert("검색할 건물명을 입력해 주세요.");
                return;
            }
            if ($c.util.getComponent('ipt_searchBldgNm').getValue().length === 1) {
                await $c.win.alert("건물명을 2자이상 입력해 주세요.");
                return;
            }
            if ($c.util.getComponent('ipt_searchBldgNm').getValue().includes('%')) {
                await $c.win.alert("입력한 건물명에 '%' 문자가 포함되어 있어 처리할 수 없습니다.");
                return;
            }
            $c.util.getComponent('ipt_searchWord').setValue(($c.util.getComponent("ipt_searchWord2").getValue() || ''));
        }
    }
    await scwin.fnSearch();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
};

/**
 * @method
 * @name setZipcdAddrInfo
 * @description set Zipcd Addr Info 처리
 * @param {*} zipcd1 zipcd1
 * @param {*} zipcd2 zipcd2
 * @param {String} addrStr addrStr
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setZipcdAddrInfo = async function (zipcd1, zipcd2, addrStr) {
    try {
        (((((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})) !== scwin && typeof (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setZipcdAddrInfo === 'function' ? (((($c.win && $c.win.getOpenerScope ? $c.win.getOpenerScope() : null) || { getComponentById: function (id) { /* TODO Stage2: [sdd] 부모 화면 스코프 없음 —  id  를 못 읽는다(단독 진입이거나 부모가 닫혔다) */ return null; }, scwin: {} }).scwin || {})).setZipcdAddrInfo(zipcd1, zipcd2, addrStr) : void 0), $c.win.closePopup([zipcd1, zipcd2, addrStr]));
        /* TODO Stage2: [sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_focus — {target}.focus({args}) */
        $c.win.closePopup();
    } catch (e) { $c.exception.handleError(e, { notify: 'none', context: 'jlddst60700' });
        await $c.win.alert("<ERROR>\n\n" + "부모창을 찾을 수가 없습니다. \n\n");
    }
};
